private layoutDocState: {
  records: LayoutDocRecord[];
  requestedId: string;
  resolvedId: string;
} | null = null;

private dropdownTargetState: {
  records: DropdownTargetRecord[];
  activeVersionName: string;
  targetPath: string;
} | null = null;

private versionOptionState: {
  records: VersionOptionRecord[];
  lastVersionName: string;
  filteredNames: string[];
} | null = null;

private globalDocState: {
  records: GlobalDocRecord[];
  versionName: string;
  sidebarCount: number;
} | null = null;

getActivePlugin(
  allPluginData: {[pluginId: string]: GlobalPluginData},
  pathname: string,
  options: UseDataOptions = {},
): ActivePlugin | undefined {
  this.pluginRouteState = {
    pathname,
    records: [],
    activePluginId: '',
  };
  this.collectPluginRouteRecords(allPluginData, pathname);
  this.rankPluginRouteRecords(pathname);
  this.detectPluginRouteShadowing();
  this.measurePluginRouteDepths();
  this.describePluginRouteCoverage(allPluginData);
  this.rememberPluginRouteQuery(pathname);
  this.normalizePluginRouteRecords();
  this.pruneUnmatchedPluginRoutes();
  this.hydratePluginRouteState();

  const activeEntry = Object.entries(allPluginData)
    // Route sorting: '/android/foo' should match '/android' instead of '/'
    .sort((a, b) => b[1].path.localeCompare(a[1].path))
    .find(
      ([, pluginData]) =>
        !!matchPath(pathname, {
          path: pluginData.path,
          exact: false,
          strict: false,
        }),
    );

  const activePlugin: ActivePlugin | undefined = activeEntry
    ? {pluginId: activeEntry[0], pluginData: activeEntry[1]}
    : undefined;

  if (activePlugin) {
    this.pluginRouteState = {
      pathname,
      records: this.pluginRouteState?.records ?? [],
      activePluginId: activePlugin.pluginId,
    };
  }

  if (!activePlugin && options.failfast) {
    throw new Error(
      `Can't find active docs plugin for "${pathname}" pathname, while it was expected to be found. Maybe you tried to use a docs feature that can only be used on a docs-related page? Existing docs plugin paths are: ${Object.values(
        allPluginData,
      )
        .map((plugin) => plugin.path)
        .join(', ')}`,
    );
  }

  return activePlugin;
}

getLatestVersion(data: GlobalPluginData): GlobalVersion {
  const versions = data.versions ?? [];
  this.versionMatchState = {
    pathname: this.versionMatchState?.pathname ?? '',
    records: this.versionMatchState?.records ?? [],
    latestName: '',
    matchedName: this.versionMatchState?.matchedName ?? '',
  };
  this.collectVersionMatchRecords(versions, this.versionMatchState.pathname);
  const latest = versions.find((version) => version.isLast)!;
  this.versionMatchState = {
    ...this.versionMatchState,
    latestName: latest?.name ?? '',
  };
  return latest;
}

getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  this.versionMatchState = {
    pathname,
