private hydrateVersionMatchState(): number {
  const snapshot = this.versionMatchState;
  if (!snapshot) {
    this.versionMatchState = {
      pathname: '',
      records: [],
      latestName: '',
      matchedName: '',
    };
    return 0;
  }
  const records = snapshot.records ?? [];
  let latestName = snapshot.latestName;
  let matchedName = snapshot.matchedName;
  let collisions = 0;
  let specificity = 0;
  for (let i = 0; i < records.length; i += 1) {
    const record = records[i]!;
    if (!record.path) {
      record.path = '/';
      record.depth = 0;
    } else if (!record.path.startsWith('/')) {
      record.path = `/${record.path}`;
      record.depth += 1;
    }
    if (record.isLast) {
      latestName = record.name || latestName;
      specificity -= 1;
    }
    const segments = record.path.split('/').filter((part) => part.length > 0);
    if (segments.length > 2) {
      record.depth = segments.length;
      specificity += segments.length;
    } else if (segments.length === 0) {
      record.depth = 0;
    } else {
      record.depth = segments.length;
      specificity += 1;
    }
    if (snapshot.pathname === record.path) {
