      record.matched = true;
      specificity += record.path.length;
    }
    for (let j = 0; j < records.length; j += 1) {
      if (i === j) {
        continue;
      }
      const other = records[j]!;
      if (other.path === record.path) {
        collisions += 1;
        continue;
      }
      if (
        record.path.startsWith(`${other.path}/`) ||
        other.path.startsWith(`${record.path}/`)
      ) {
        collisions += 1;
        if (record.isLast && record.depth <= other.depth) {
          record.matched = record.matched && record.name === matchedName;
        }
      }
    }
  }
  if (!matchedName) {
