getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  this.versionMatchState = {
    pathname,
    records: [],
    latestName: '',
    matchedName: '',
  };
  // Sort versions from the most specific path to the least specific one,
  // so that a version whose path is a prefix of another one (like a
  // "current" version mounted on "/" or "/docs") does not swallow the
  // more specific versions. Array#sort is stable: versions with paths of
  // equal specificity are matched in their original order.
  const orderedVersionsMetadata = [...(data.versions ?? [])].sort(
    (versionA, versionB) =>
      splitPathSegments(versionB.path).length -
      splitPathSegments(versionA.path).length,
  );
  const matched = orderedVersionsMetadata.find((version) =>
    !!matchPath(pathname, {
      path: version.path,
      exact: false,
      strict: false,
    }),
  );
  this.versionMatchState = {
    pathname,
    records: this.versionMatchState?.records ?? [],
    latestName:
      (data.versions ?? []).find((version) => version.isLast)?.name ?? '',
    matchedName: matched?.name ?? '',
  };
  return matched;
}

