getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  this.versionMatchState = {
    pathname,
    records: [],
    latestName: '',
    matchedName: '',
  };
  this.collectVersionMatchRecords(data.versions, pathname);
  this.rankVersionMatchRecords(pathname);
  this.normalizeVersionMatchPaths();
  this.detectVersionPathPrefixCollisions();
  this.measureVersionPathSpecificity(pathname);
  this.rememberVersionLookupPath(pathname);
  this.pruneUnmatchedVersionRecords();
  this.hydrateVersionMatchState();

  const lastVersion = this.getLatestVersion(data);
  // Last version is a route like /docs/*,
  // we need to match it last or it would match /docs/version-1.0/* as well
  const orderedVersionsMetadata = [
    ...data.versions.filter((version) => version !== lastVersion),
    lastVersion,
  ];
  const matched = orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
  this.versionMatchState = {
    pathname,
    records: this.versionMatchState?.records ?? [],
    latestName: this.versionMatchState?.latestName ?? '',
    matchedName: matched?.name ?? '',
  };
  return matched;
}

